"use strict";
// Original local play; fictional points and messages, with no real paid services.
const pocketSouvenirs=['玻璃弹珠','公交月票','游戏厅代币','星星折纸','彩色电话卡','海边明信片','透明磁带','毕业留言册','旧车票','四叶草书签','像素徽章','蓝色贝壳'];
const pocketRoutes=[
 {id:0,title:'放学旧巷',desc:'穿过小卖部、游戏厅和路灯下的巷口。',level:1,enemy:['纸箱怪','发条青蛙','路灯守卫'],symbols:['▣','♧','♜'],bonus:0},
 {id:1,title:'雨后车站',desc:'雨伞、末班车和没寄出的明信片。对手蓄力时记得防守。',level:2,enemy:['雨伞精','纸票巡逻员','末班车影'],symbols:['☂','▤','▥'],bonus:4},
 {id:2,title:'天台夏夜',desc:'沿着旧楼梯，去看看城市最后亮着的灯。',level:3,enemy:['风筝怪','天线信使','星空守望者'],symbols:['◇','Ψ','★'],bonus:8}
];
const pocketGoals=[{id:'first',title:'第一次平安回家',desc:'完成任意一次三站探险',reward:12,test:c=>c.wins>=1},{id:'angler',title:'河边的老朋友',desc:'累计钓到3条鱼',reward:15,test:c=>c.fish>=3},{id:'drawer',title:'装满半个抽屉',desc:'找到6种不同纪念品',reward:20,test:c=>c.collection.length>=6},{id:'walks',title:'放学路上的常客',desc:'累计完成5次探险',reward:30,test:c=>c.wins>=5}];
function pocketClubLoad(raw){const d={name:'小团',level:1,xp:0,coins:20,energy:6,mood:70,collection:[],notes:[],wins:0,fish:0,best:0,claimed:[]};try{const p=JSON.parse(raw||'{}');for(const k of ['level','xp','coins','energy','mood','wins','fish','best'])if(Number.isSafeInteger(p[k])&&p[k]>=0)d[k]=Math.min(p[k],k==='energy'?6:k==='mood'?100:k==='level'?99:99999);if(Array.isArray(p.claimed))d.claimed=[...new Set(p.claimed.filter(id=>pocketGoals.some(g=>g.id===id)))];const b=p.battle;if(b&&Number.isInteger(b.stage)&&b.stage>=1&&b.stage<=3&&Number.isInteger(b.route)&&b.route>=0&&b.route<3&&['hp','max','enemy','turn','potions'].every(k=>Number.isSafeInteger(b[k])&&b[k]>=0)&&b.hp>0&&b.hp<=b.max&&b.max<=500&&b.enemy>0&&b.enemy<=100&&b.turn<10000&&b.potions<=2)d.battle={stage:b.stage,route:b.route,hp:b.hp,max:b.max,enemy:b.enemy,turn:b.turn,potions:b.potions,log:typeof b.log==='string'?b.log.slice(0,240):'回到离开时的路口。'};if(typeof p.name==='string')d.name=p.name.slice(0,12)||'小团';if(Array.isArray(p.collection))d.collection=[...new Set(p.collection.filter(n=>Number.isInteger(n)&&n>=0&&n<pocketSouvenirs.length))];if(Array.isArray(p.notes))d.notes=p.notes.filter(n=>typeof n==='string').slice(-8).map(n=>n.slice(0,140));}catch{}d.level=Math.max(1,d.level);return d;}
let pocketClub=pocketClubLoad(localStorage.getItem('olddays-pocket-club')),pocketClubPage='home',pocketBattle=pocketClub.battle||null,pocketCast=0,pocketClubNotice='';
function pocketClubSave(){if(pocketBattle)pocketClub.battle={...pocketBattle};else delete pocketClub.battle;try{localStorage.setItem('olddays-pocket-club',JSON.stringify(pocketClub));}catch{}}
function pocketClubNote(t){pocketClub.notes.push(t);pocketClub.notes=pocketClub.notes.slice(-8);}
function pocketClubXP(n){pocketClub.xp+=n;while(pocketClub.xp>=pocketClub.level*12&&pocketClub.level<99){pocketClub.xp-=pocketClub.level*12;pocketClub.level++;pocketClub.coins+=8;pocketClubNote('小团长大了一点。新等级 '+pocketClub.level+'，收到8枚零花钱。');}}
function pocketClubCollect(index){if(!pocketClub.collection.includes(index)){pocketClub.collection.push(index);pocketClubNote('收到纪念品：'+pocketSouvenirs[index]+'。已放入抽屉。');return true;}pocketClub.coins+=3;return false;}
function pocketClubAction(action,now=Date.now(),random=Math.random){pocketClubNotice='';if(action==='feed'){if(pocketClub.coins<4){pocketClubNotice='零花钱不够，去钓鱼或玩一局赚一点吧。';return false;}pocketClub.coins-=4;pocketClub.energy=Math.min(6,pocketClub.energy+3);pocketClub.mood=Math.min(100,pocketClub.mood+12);pocketClubNotice='热乎乎的饭团！体力 +3，心情 +12。';}
else if(action==='resume'){if(!pocketBattle)return false;pocketClubPage='battle';}
else if(action.startsWith('claim:')){const g=pocketGoals.find(g=>g.id===action.slice(6));if(!g||pocketClub.claimed.includes(g.id)||!g.test(pocketClub))return false;pocketClub.claimed.push(g.id);pocketClub.coins+=g.reward;pocketClubNotice='小卖部的奖励：'+g.reward+'枚零花钱。';}
else if(action==='routes'||action==='goals'){pocketClubPage=action;}
else if(action==='start'||/^route:[0-2]$/.test(action)){if(pocketBattle){pocketClubPage='battle';pocketClubNotice='先走完这一次，再换条路。';return true;}const route=action==='start'?0:Number(action.slice(6));if(pocketClub.level<pocketRoutes[route].level){pocketClubNotice='先和小团一起长大一点，这条路需要 Lv.'+pocketRoutes[route].level;return false;}if(!pocketClub.energy){pocketClubNotice='先吃点东西恢复体力。钓鱼不用体力。';return false;}pocketClub.energy--;pocketBattle={stage:1,route,hp:24+pocketClub.level*4,max:24+pocketClub.level*4,enemy:16+pocketRoutes[route].bonus,turn:0,potions:2,log:pocketRoutes[route].title+'，'+pocketRoutes[route].enemy[0]+'挡住了去路。'};pocketClubPage='battle';}
else if(['attack','guard','potion','run'].includes(action)){if(!pocketBattle)return false;const b=pocketBattle;if(action==='run'){pocketClubPage='home';pocketBattle=null;pocketClubNotice='带着小团回家了，下次再来。';}
else{if(action==='potion'&&!b.potions){pocketClubNotice='背包里的两瓶汽水已经喝完。';return false;}b.turn++;if(action==='potion'){if(!b.potions){pocketClubNotice='背包里的两瓶汽水已经喝完。';return false;}b.potions--;b.hp=Math.min(b.max,b.hp+14);b.log='喝了汽水，恢复14点精神。';}else{const damage=action==='guard'?3:6+pocketClub.level+Math.floor(random()*4);b.enemy-=damage;b.log=(action==='guard'?'抱紧书包防守，反击':'小团使出弹珠攻击')+'，造成'+damage+'点伤害。';}if(b.enemy<=0){pocketClub.coins+=8;pocketClubXP(5);if(b.stage===3){pocketClub.wins++;pocketClubCollect((b.route*3+Math.floor(random()*3))%8);pocketClubXP(10);pocketClubNote('和小团一起走完旧巷，路灯亮起来的时候刚好到家。');pocketClubNotice='闯过三站！赢得24枚零花钱、25经验和一件纪念品。';pocketBattle=null;pocketClubPage='home';}else{b.stage++;b.enemy=12+b.stage*5+pocketRoutes[b.route].bonus;b.hp=Math.min(b.max,b.hp+7);b.log='过关！捡到8枚零花钱，恢复7点精神。下一站：'+pocketRoutes[b.route].enemy[b.stage-1]+'。';}}else{const charged=b.route>0&&b.turn%3===0;const hit=action==='guard'?2:4+b.stage+Math.floor(random()*3)+(charged?6:0);if(charged)b.log+=' 对手蓄力出击！';b.hp-=hit;b.log+=' 对手反击'+hit+'点。';if(b.hp<=0){pocketClub.coins+=2;pocketClubXP(2);pocketClubNotice='小团累了。路过的店员送你们回家，留下2枚车费。';pocketBattle=null;pocketClubPage='home';}}}}
else if(action==='cast'){pocketCast=now;pocketClubPage='fishing';pocketClubNotice='浮标进入浅色区域时收杆。';}
else if(action==='catch'){if(!pocketCast)return false;const progress=((now-pocketCast)%1800)/1800;pocketCast=0;const caught=progress>=.34&&progress<=.66;if(caught){pocketClub.fish++;pocketClub.coins+=5;pocketClubXP(3);pocketClubCollect(8+Math.floor(random()*4));pocketClubNotice='钓到了！零花钱 +5、经验 +3，看看收藏抽屉。';}else{pocketClub.coins++;pocketClubNotice='鱼溜走了，捡到1枚零花钱。再试一次？';}}
else if(action==='home'){pocketClubPage='home';pocketCast=0;}
else if(action==='collection'||action==='letters'||action==='fishing')pocketClubPage=action;
else return false;pocketClubSave();return true;}
function pocketClubMarkup(){const c=pocketClub,button=(id,t)=>'<button data-pocket-club="'+id+'">'+t+'</button>';let body='';if(pocketClubPage==='battle'&&pocketBattle){const b=pocketBattle;body='<div class="club-battle"><small>'+pocketRoutes[b.route].title+' · 第 '+b.stage+' / 3 站</small><div class="club-enemy">'+pocketRoutes[b.route].symbols[b.stage-1]+'</div><b>'+pocketRoutes[b.route].enemy[b.stage-1]+' · '+Math.max(0,b.enemy)+' HP</b>'+(b.route>0&&(b.turn+1)%3===0?'<p class="club-warning">对手正在蓄力……</p>':'')+'<p>小团精神 '+b.hp+' / '+b.max+'</p><meter min="0" max="'+b.max+'" value="'+Math.max(0,b.hp)+'"></meter><p aria-live="polite">'+escapeHTML(b.log)+'</p><div class="club-actions">'+button('attack','1 弹珠攻击')+button('guard','2 书包防守')+button('potion','3 喝汽水 ('+b.potions+')')+button('run','回家')+'</div></div>';}
else if(pocketClubPage==='fishing'){body='<div class="club-lake"><span>☁　　☁</span><strong>⌁　⌁　⌁</strong><p>河边的下午，什么也不用着急。</p></div>'+(pocketCast?'<div class="club-fishing-bar"><i></i><b></b></div>'+button('catch','5 现在收杆！'):button('cast','抛下鱼竿'))+'<p>在浮标经过中间浅色区域时收杆。钓鱼不消耗体力，没钓到也会捡到零花钱。</p>';}
else if(pocketClubPage==='routes'){body='<h3>今天走哪条路？</h3><div class="club-route-list">'+pocketRoutes.map(r=>'<article><small>路线 0'+(r.id+1)+' · Lv.'+r.level+'</small><h3>'+r.title+'</h3><p>'+r.desc+'</p>'+button('route:'+r.id,c.level>=r.level?'出发 →':'Lv.'+r.level+' 解锁')+'</article>').join('')+'</div><p>数字键1 / 2 / 3选路线，0返回。每次消耗1点体力，连走三站。离开或刷新后可从家里继续，不会重复扣体力。</p>';}
else if(pocketClubPage==='goals'){body='<h3>小卖部门口的愿望单</h3>'+pocketGoals.map(g=>'<article class="club-goal"><b>'+g.title+'</b><p>'+g.desc+' · 奖励 '+g.reward+'零花钱</p>'+(c.claimed.includes(g.id)?'<span>✓ 已领取</span>':g.test(c)?button('claim:'+g.id,'领取奖励'): '<span>慢慢来，还在路上</span>')+'</article>').join('');}
else if(pocketClubPage==='collection'){body='<h3>抽屉里的青春 · '+c.collection.length+' / 12</h3><div class="club-collection">'+pocketSouvenirs.map((t,i)=>'<article class="'+(c.collection.includes(i)?'found':'')+'"><b>'+['◉','▤','◈','★','▧','✉','▣','▥','▤','♧','✣','◔'][i]+'</b><span>'+(c.collection.includes(i)?t:'未找到')+'</span></article>').join('')+'</div><p>探险与河边垂钓，会带回不同的小东西。</p>';}
else if(pocketClubPage==='letters'){body='<h3>小团的来信</h3>'+(c.notes.length?c.notes.slice().reverse().map(n=>'<blockquote>'+escapeHTML(n)+'</blockquote>').join(''):'<blockquote>你好呀。放学以后，你愿意带我出去走走吗？<br>—— 小团</blockquote>');}
else body='<div class="club-home-label">放学后 · 记得回来看看</div><div class="club-pet"><span>✦　　✧</span><strong>(•ᴗ•)</strong><b>'+escapeHTML(c.name)+' · Lv.'+c.level+'</b><small>等你下课的小伙伴</small></div><div class="club-stats"><span>体力 <b>'+c.energy+'/6</b></span><span>心情 <b>'+c.mood+'/100</b></span><span>零花钱 <b>'+c.coins+'</b></span></div><p>经验 '+c.xp+' / '+c.level*12+' · 闯关 '+c.wins+' 次 · 钓鱼 '+c.fish+' 条</p><div class="club-actions">'+(pocketBattle?button('resume','▶ 继续第'+pocketBattle.stage+'站'):button('routes','✦ 选一条探险路线'))+button('fishing','⌁ 河边钓鱼')+button('feed','饭团 · 4零花钱')+button('collection','▤ 收藏抽屉')+button('letters','✉ 小团来信')+button('goals','☆ 小卖部愿望单')+'</div><details><summary>怎么玩？</summary><p>三条路线随等级解锁，探险连闯三站，可攻击、防守、喝汽水；通关涨经验、赚零花钱、收集纪念品。钓鱼考验收杆时机，喂饭恢复体力。战斗与成长都保存在本机，可随存档盒备份。均为原创网页玩法。</p></details>';
return '<section class="pocket-club"><header><small>POCKET PAL / 原创养成</small><h2>放学别关机</h2>'+button('home','⌂ 小团的家')+'</header>'+body+(pocketClubNotice?'<p class="club-notice" role="status">'+escapeHTML(pocketClubNotice)+'</p>':'')+'<footer>本机存档 · 没有真实消费</footer></section>';}
phoneApps.push(['pocketclub','放学别关机','✦']);systemApps.push({id:'pocketclub',name:'放学别关机',icon:'✦',color:'lime',desc:'养小团、探险战斗、钓鱼和收藏'});systemInstalled.push('pocketclub');
const pocketClubAllowedBase=phoneAppAllowed,pocketClubScreenBase=phoneScreen,pocketClubShelfBase=phoneGameShelfMarkup;
phoneAppAllowed=function(app){return app==='pocketclub'?!isTextOnlyPhone()&&!deviceCapabilities[phoneState.model]:pocketClubAllowedBase(app);};
phoneScreen=function(){return phoneState.app==='pocketclub'&&phoneAppAllowed('pocketclub')?pocketClubMarkup():pocketClubScreenBase();};
phoneGameShelfMarkup=function(){return '<button class="club-entry" data-phone-app="pocketclub"><b>✦ 放学别关机</b><span>养小团 · 回合探险 · 钓鱼 · 收集12件纪念品 →</span></button>'+pocketClubShelfBase();};
document.addEventListener('click',e=>{const b=e.target.closest('[data-pocket-club]');if(!b)return;e.preventDefault();pocketClubAction(b.getAttribute('data-pocket-club'));refreshPhone();});
function pocketClubHardware(key){if(key==='0'){pocketClubAction('home');refreshPhone();return true;}const action=pocketClubPage==='routes'?({'1':'route:0','2':'route:1','3':'route:2'}[key]):pocketClubPage==='goals'?({'1':'claim:first','2':'claim:angler','3':'claim:drawer','4':'claim:walks'}[key]):pocketClubPage==='battle'?({'1':'attack','2':'guard','3':'potion','5':'attack'}[key]):pocketClubPage==='fishing'&&key==='5'?(pocketCast?'catch':'cast'):({'1':pocketBattle?'resume':'routes','2':'fishing','3':'feed','4':'collection','5':'letters','6':'goals'}[key]);if(!action)return false;pocketClubAction(action);refreshPhone();return true;}
document.addEventListener('click',e=>{if(phoneState.app!=='pocketclub')return;const b=e.target.closest('[data-phone-key],[data-phone-ok]');if(!b)return;const key=b.hasAttribute('data-phone-ok')?'5':b.getAttribute('data-phone-key');if(pocketClubHardware(key)){e.preventDefault();e.stopImmediatePropagation();}},true);
document.addEventListener('keydown',e=>{if(phoneState.app!=='pocketclub'||e.target.matches?.('input,textarea,select'))return;if(pocketClubHardware(e.key==='Enter'?'5':e.key)){e.preventDefault();e.stopImmediatePropagation();}},true);
const pocketClubSmsBase=phoneSmsMarkup;
phoneSmsMarkup=function(){const base=pocketClubSmsBase();if(typeof experienceZone==='undefined'||experienceZone!=='phone'||!pocketClub.notes.length)return base;return '<details class="club-sms"><summary>✉ 放学别关机 · '+pocketClub.notes.length+' 条游戏来信</summary>'+pocketClub.notes.slice(-3).reverse().map(t=>'<p>'+escapeHTML(t)+'</p>').join('')+'<button data-phone-app="pocketclub">打开小团的家 →</button><small>本机游戏消息，非真实短信</small></details>'+base;};
